[Fact]
public async Task AC5_SourceDeclaredGenericStructDiagnosticsStillReported()
{
    // Same shape as the repro, but Item<T> is declared in the same project and has a member missing [Key].
    string source = """
        using MessagePack;
        namespace App;

        [MessagePackObject]
        public partial struct Item<T>
        {
            [Key(0)] public string Key { get; set; }
            public string Missing { get; set; }
        }

        [MessagePackObject]
        public sealed partial record Cmd([property: Key(0)] string Scope)
        {
            [Key(1)] public Item<int> Member { get; init; }
        }
        """;
    var refs = await BaseReferencesAsync();
    var app = Compile("App", source, refs);
    var diags = await this.RunAnalyzerAsync(app);
    Assert.DoesNotContain(diags, d => d.Id == "AD0001");

    int expectedStart = source.IndexOf("Missing", StringComparison.Ordinal);
    var msgpack004 = diags.Where(d => d.Id == "MsgPack004").ToList();
    Assert.NotEmpty(msgpack004);
    Assert.Contains(msgpack004, d => d.Location.IsInSource && d.Location.SourceSpan.Start == expectedStart && d.Location.SourceSpan.Length == "Missing".Length);
}

